mapper.select:
SELECT
    (SELECT COUNT(*) FROM product WHERE status = 1) AS totalProducts,
    (SELECT COUNT(*) FROM customer) AS totalCustomers,
    (SELECT COUNT(*) FROM `order`

         AND order_date >= #{startDate}
         AND order_date <= #{endDate}

    ) AS totalOrders,
    (SELECT COALESCE(SUM(total_amount), 0) FROM `order`
     WHERE order_status != 'CANCELLED'
     AND order_date >= #{startDate}
     AND order_date <= #{endDate}
    ) AS totalRevenue
FROM DUAL

SELECT order_status AS status, COUNT(*) AS count FROM `order`
AND order_date >= #{startDate} AND order_date <= #{endDate}
GROUP BY order_status
